    "general_conditions": "| 項目 | 内容 |\n| --- | --- |\n| 対応環境 | macOSのGoogle Chromeを推奨します。本ガイドは0.4.32 BETAを対象にしています。 |\n| 必要なアカウント | このアプリの作図・ブラウザ保存にはログインはありません。授業の提出先で必要なアカウントは、その提出先の案内に従います。 |\n| 対象となる利用モード | 通常の編集画面、キャンバス内の試し再生、発表表示、発表者ビューと投影画面、書き出した再生用HTMLです。課題専用モードはありません。 |\n| 利用を始める前の条件 | アプリのファイルを読み込める接続と、JavaScriptを使えるブラウザが必要です。ブラウザ内への保存には、そのブラウザの保存領域を使えることが必要です。 |\n| ファイルへの保存 | Chromeで保存先を選ぶ方式と、再編集用ZIPをダウンロードする方式があります。ローカル自動保存には、対応するChromeで保存先を選ぶ必要があります。 |\n| 発表者ビュー | 手元と投影用の2つのウィンドウを使います。別の画面へ投影する場合はOSの拡張表示を使い、投影用ウィンドウを自分で移動します。 |\n\n本文の「通常編集画面」は、この章の条件で開いた編集用の画面を指します。⌘はMacのCommandキー、OptionはOptionキーです。入力欄で文章を編集中のときは、編集面のショートカットとは動作が異なります。\n\nブラウザ保存は、その端末・そのブラウザに保存します。別の端末やブラウザで続ける場合は、再編集用ファイルを持ち出してください。",
