        "caution": "同名のファイルを指定する場合は、上書きしてよいか確認してください。以前の版も残したいときは、別の名前で保存します。ダウンロード方式ではブラウザ側の保存が完了したことも確認します。画像を書き出しただけでは、この再編集用保存の代わりになりません。",
